enu: [], readOnly: false, stats: [], items: [] }, { id: "Id 2", type: "Type 2", label: "Label 2", required: true, repeatable: true, options: [], condition: [], placeholder: "Placeholder 2", entityField: "Entity Field 2", minLength: 2, maxLength: 2, displayFields: [], hiddenCalculations: [], contextMenu: [], readOnly: true, stats: [], items: [] }], subsections: [], condition: [], repeatable: true, minItems: 2, addButtonLabel: "Add Button Label 2", hiddenCalculations: [{ variable: "Variable", expression: "Expression", scope: "Scope" }, { variable: "Variable 2", expression: "Expression 2", scope: "Scope 2" }], readOnly: true }], globalVariablesRequired: ["Item", "Item 2"], globalVariablesSet: ["Item", "Item 2"], localVariables: ["Item", "Item 2"], entityMapping: { entity: "Entity 2", mode: "create_multiple", parentField: "Parent Field 2", idField: "Id Field 2" }, validationRules: [{ condition: [], message: "Message" }, { condition: [], message: "Message 2" }], lawReferences: [{ law: "Law", article: "Article", description: "Description" }, { law: "Law 2", article: "Article 2", description: "Description 2" }], phase: "Phase 2", contextMenu: ["Item", "Item 2"] }]
        @label "Steps"
        @description "Wizard steps"
        @tier "presentation"
      currentStep : string
        @label "Current Step"
        @description "Current step index (controlled) - accepts number or string for generated code compatibility"
        @tier "presentation"
      onStepChange : event = "STEP_CHANGE"
        @label "On Step Change"
        @description "Callback when step changes"
        @tier "presentation"
      onComplete : event = "COMPLETE"
        @label "On Complete"
        @description "Callback when wizard is completed"
        @tier "presentation"
      showProgress : boolean = true
        @label "Show Progress"
        @description "Show progress indicator"
        @tier "presentation"
      allowBack : boolean = true
        @label "Allow Back"
        @description "Allow navigation to previous steps"
        @tier "presentation"
      compact : boolean = false
        @label "Compact"
        @description "Modal mode (compact header, no padding)"
        @tier "presentation"
      className : string
        @label "Class Name"
        @description "Additional CSS classes"
        @tier "presentation"
      isLoading : boolean
        @label "Is Loading"
        @description "Loading state indicator"
        @tier "presentation"
      error : WizardContainerError
        @label "Error"
        @description "Error state"
        @tier "presentation"
      nextEvent : event = "NEXT"
        @label "Next Event"
        @description "Emits UI:{nextEvent} when advancing to next step"
        @tier "presentation"
      backEvent : event = "BACK"
        @label "Back Event"
        @description "Emits UI:{backEvent} when going to previous step"
        @tier "presentation"
      completeEvent : event = "COMPLETE"
        @label "Complete Event"
        @description "Emits UI:{completeEvent} when wizard completes"
        @tier "presentation"
